const host=document.querySelector('#screenHost');function showScreen(n){let s=screenData[n];host.innerHTML=`<div class="screen-head"><div><p class="eyebrow"><span></span>${s.tag}</p><h2>${s.title}</h2><p>${s.sub}</p></div><button class="primary">+ Add transaction</button></div>${s.body}`;document.querySelector('#screenName').textContent=document.querySelector(`[data-screen="${n}"] span`).textContent;document.querySelectorAll('.app-nav').forEach(x=>x.classList.toggle('active',x.dataset.screen===n));host.querySelectorAll('[data-screen]').forEach(x=>x.onclick=()=>showScreen(x.dataset.screen));host.querySelector('.sim-run')?.addEventListener('click',e=>e.currentTarget.textContent='Simulation updated ✓')};document.querySelectorAll('.app-nav').forEach(x=>x.onclick=()=>{showScreen(x.dataset.screen);document.querySelector('#app').scrollIntoView({behavior:'smooth'})});document.querySelector('.mobile-menu').onclick=()=>document.querySelector('.app-sidebar').classList.toggle('open');showScreen('overview');
